import {KEY,empty,upsert,decision,undo,remove,monthly,visible,hydrate,STAGES} from './organizer.js';
const $=id=>document.getElementById(id),node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
const button=(text,fn)=>{const b=node('button',text);b.type='button';b.onclick=fn;return b;};
const money=value=>value===null?'Unknown':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(value);
let state=empty(),view='deck',filter={},editing=null,comparison=false,pending=null,timer,readError=false,rawBackup=null;
function announce(message){clearTimeout(timer);$('organizer-announcement').textContent=message;$('organizer-announcement').hidden=false;timer=setTimeout(()=>$('organizer-announcement').hidden=true,5000);}
function commit(next,{recovery=false}={}){if(readError&&!recovery){announce('Saved data could not be read. Download a backup, restore a valid backup, or clear the organizer first.');return false;}state=next;readError=false;try{localStorage.setItem(KEY,JSON.stringify(state));rawBackup=null;$('local-status').textContent='Saved on this browser only. No account or cloud sync. Download a backup before clearing browser data.';}catch{$('local-status').textContent='Storage unavailable or full: changes are temporary and will be lost when you leave. Download a backup to keep them.';}render();return true;}
function ask(title,copy,action){pending=action;$('confirm-title').textContent=title;$('confirm-copy').textContent=copy;$('organizer-confirm').showModal();}
$('confirm-cancel').onclick=()=>{pending=null;$('organizer-confirm').close();};
$('confirm-action').onclick=()=>{const action=pending;pending=null;$('organizer-confirm').close();action?.();};
$('organizer-confirm').addEventListener('cancel',()=>pending=null);
function resetForm(){editing=null;$('link-form').reset();$('form-heading').textContent='Add a rental';$('submit-link').textContent='Add to my deck';$('cancel-edit').hidden=true;$('link-error').hidden=true;}
function edit(row){editing=row.id;for(const [key,value]of Object.entries(row)){const field=$('link-form').elements.namedItem(key);if(field)field.value=value??'';}$('form-heading').textContent='Edit rental link';$('submit-link').textContent='Save changes';$('cancel-edit').hidden=false;$('link-error').hidden=true;$('link-form').elements.namedItem('title').focus();}
function choose(id,choice){if(!commit(decision(state,id,choice)))return;const remaining=visible(state.items,filter).filter(r=>r.decision===null);if(view==='deck'&&!remaining.length&&state.items.some(r=>r.decision==='save')){view='saved';render();$('view-saved').focus();announce('Deck complete. Your saved links are ready to compare.');}else announce(choice==='save'?'Saved. No one has been contacted.':choice==='pass'?'Passed. Undo brings it back.':'Back in your deck.');}
function card(row){const article=node('article',undefined,'personal-card');article.tabIndex=0;article.setAttribute('aria-label',row.title+(view==='deck'?'. Left arrow passes; right arrow saves.':''));
  const banner=node('div',undefined,'source-banner');banner.append(node('p','PERSONAL BOOKMARK · NOT VERIFIED','eyebrow'),node('span',new URL(row.url).hostname));article.append(banner);
  const body=node('div',undefined,'card-body'),top=node('div',undefined,'listing-top'),total=monthly(row);top.append(node('h3',row.title));const price=node('div',money(total),'price');price.append(node('small','your entered monthly total'));top.append(price);body.append(node('p',row.city||'Location not entered','location'),top);
  body.append(node('p','Rent '+money(row.rent)+' + utilities '+money(row.utilities)+' + recurring fees '+money(row.fees)+'. Deposit: '+money(row.deposit)+'.','costs'));
  const pills=node('div',undefined,'pills');for(const label of [row.bedrooms===null?'Bedrooms unknown':row.bedrooms===0?'Studio / room':row.bedrooms+' bedrooms','Furnished: '+row.furnished,'Utilities included: '+row.utilitiesIncluded])pills.append(node('span',label,'pill'));body.append(pills);
  if(total===null)body.append(node('p','Total unknown. Missing costs are not assumed to be $0.','help'));
  if(row.start)body.append(node('p','Your planned stay: '+row.start+' to '+row.end+'. Availability is not verified.','help'));
  body.append(node('p','Entered by you. Last edited '+new Date(row.updated).toLocaleDateString()+'. Recheck price, fees and availability on the source site.','help'));
  if(row.notes)body.append(node('p',row.notes,'notes'));
  const source=node('a','Open original listing ↗','primary source-link');source.href=row.url;source.target='_blank';source.rel='noopener noreferrer';source.referrerPolicy='no-referrer';source.setAttribute('aria-label','Open original listing for '+row.title+' on '+new URL(row.url).hostname);body.append(source);
  const controls=node('div',undefined,'actions');if(row.decision!=='save')controls.append(button('Save →',()=>choose(row.id,'save')));if(row.decision!=='pass')controls.append(button('← Pass',()=>choose(row.id,'pass')));if(row.decision)controls.append(button('Back to deck',()=>choose(row.id,null)));body.append(controls);
  if(row.decision==='save'){const label=node('label','My progress (private)'),select=node('select');select.setAttribute('aria-label','Progress for '+row.title);for(const value of STAGES){const o=node('option',value);o.value=value;select.append(o);}select.value=row.stage;select.onchange=()=>{const next=structuredClone(state);next.items.find(r=>r.id===row.id).stage=select.value;commit(next);};label.append(select);body.append(label);}
  const manage=node('div',undefined,'card-controls');manage.append(button('Edit details & notes',()=>edit(row)),button('Delete link',()=>ask('Delete this link?','This removes “'+row.title+'” and its notes from this browser. You can only recover it from a previously downloaded backup.',()=>{if(commit(remove(state,row.id))){if(editing===row.id)resetForm();announce('Link deleted. Other links are unchanged.');}})));body.append(manage);article.append(body);
  article.onkeydown=event=>{if(view==='deck'&&event.target===article&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();choose(row.id,event.key==='ArrowLeft'?'pass':'save');}};
  let gesture=null;article.onpointerdown=event=>{if(view!=='deck'||event.target.closest('button,a,select,input,textarea'))return;gesture={x:event.clientX,y:event.clientY,id:event.pointerId};};article.onpointercancel=()=>gesture=null;article.onpointerup=event=>{if(!gesture||gesture.id!==event.pointerId)return;const dx=event.clientX-gesture.x,dy=event.clientY-gesture.y;gesture=null;if(Math.abs(dx)>80&&Math.abs(dx)>Math.abs(dy)*1.5)choose(row.id,dx>0?'save':'pass');};return article;
}
function renderComparison(){const rows=visible(state.items,filter).filter(r=>r.decision==='save');$('personal-comparison').hidden=!comparison||!rows.length;$('compare-links').disabled=!rows.length;$('compare-links').setAttribute('aria-expanded',String(comparison&&rows.length>0));if(!comparison)return;
  const table=node('table');table.append(node('caption','Your entered USD monthly costs—not live quotes. Blank amounts remain unknown. Deposits and one-time charges are not included in monthly totals.'));const head=node('thead'),tr=node('tr');for(const text of ['Place / source','Rent','Utilities','Recurring fees','Monthly total','Deposit']){const th=node('th',text);th.scope='col';tr.append(th);}head.append(tr);table.append(head);const body=node('tbody');for(const row of rows){const tr=node('tr'),th=node('th',row.title+' · '+new URL(row.url).hostname);th.scope='row';tr.append(th);for(const value of [row.rent,row.utilities,row.fees,monthly(row),row.deposit])tr.append(node('td',money(value)));body.append(tr);}table.append(body);$('personal-comparison').replaceChildren(table);
}
function render(){const filtered=visible(state.items,filter),rows=view==='all'?filtered:filtered.filter(r=>view==='saved'?r.decision==='save':r.decision===null);$('link-count').textContent=state.items.length+' links · '+state.items.filter(r=>r.decision==='save').length+' saved';for(const key of ['deck','saved','all'])$('view-'+key).setAttribute('aria-pressed',String(view===key));$('personal-cards').replaceChildren(...(view==='deck'?rows.slice(0,1):rows).map(card));$('organizer-empty').hidden=rows.length>0;$('organizer-empty').textContent=readError?'Saved data could not be read. It has not been overwritten. Use backup controls below.':!state.items.length?'Start with a public listing link. Add a nickname and any details you know—no account needed.':!filtered.length?'No links match these filters. Clear filters to see your other places.':view==='deck'?'You’ve reviewed this deck. Open Saved, review passed links, or add another place.':view==='saved'?'No saved links match this view. Save a place from your deck or All links.':'No links yet.';$('organizer-undo').disabled=!state.history.length;$('review-links').disabled=!state.items.some(r=>r.decision==='pass');$('submit-link').disabled=readError;$('export-links').disabled=!(state.items.length||rawBackup);renderComparison();}
$('link-form').onsubmit=event=>{event.preventDefault();try{const input=Object.fromEntries(new FormData(event.currentTarget));const wasEditing=editing;if(commit(upsert(state,input,editing))){resetForm();if(!wasEditing){filter={};$('organizer-filter').reset();view='deck';render();}announce(wasEditing?'Bookmark updated. Details remain unverified.':'Added to your deck. No listing page was fetched.');}}catch(error){$('link-error').textContent=error.message;$('link-error').hidden=false;}};
$('cancel-edit').onclick=resetForm;
for(const key of ['deck','saved','all'])$('view-'+key).onclick=()=>{view=key;render();};
$('organizer-filter').onsubmit=event=>{event.preventDefault();const next=Object.fromEntries(new FormData(event.currentTarget));try{visible(state.items,next);filter=next;$('filter-error').hidden=true;render();}catch(error){$('filter-error').textContent=error.message;$('filter-error').hidden=false;}};
$('reset-filter').onclick=()=>{filter={};$('organizer-filter').reset();$('filter-error').hidden=true;render();};
$('organizer-undo').onclick=()=>{if(commit(undo(state))){view='deck';render();announce('Last swipe undone.');}};
$('review-links').onclick=()=>{const next=structuredClone(state);for(const row of next.items)if(row.decision==='pass')row.decision=null;next.history=[];if(commit(next)){view='deck';render();}};
$('compare-links').onclick=()=>{comparison=!comparison;renderComparison();};
$('clear-links').onclick=()=>ask('Clear all personal rental links?','This removes only this organizer’s links, notes and decisions. Discover saves and previous demo profiles remain untouched. Download a backup first if you want to recover these links.',()=>{if(commit(empty(),{recovery:true})){resetForm();filter={};$('organizer-filter').reset();view='deck';render();announce('Personal organizer cleared. Other NestMatch data is unchanged.');}});
$('export-links').onclick=()=>{const blob=new Blob([readError&&rawBackup?rawBackup:JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='nestmatch-personal-links-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Backup downloaded. It contains your private links and notes; keep it somewhere safe.');};
$('import-links').onclick=()=>$('backup-file').click();
$('backup-file').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>5000000)throw Error('Backup must be smaller than 5 MB.');const next=hydrate(JSON.parse(await file.text()));ask('Replace this organizer with your backup?',`This replaces all ${state.items.length} current personal links with ${next.items.length} backup links. Download your current backup first if needed. Discover saves are unaffected.`,()=>{if(commit(next,{recovery:true})){resetForm();filter={};$('organizer-filter').reset();view='all';render();announce('Backup restored. Links remain private to this browser.');}});}catch{announce('Backup is invalid or too large. No links were changed.');}};
try{rawBackup=localStorage.getItem(KEY);if(rawBackup){if(rawBackup.length>5000000)throw Error('Oversized storage');state=hydrate(JSON.parse(rawBackup));rawBackup=null;}}catch{readError=true;$('local-status').textContent='Could not read saved organizer data. Existing data has not been overwritten. Download a backup before restoring or clearing.';}
render();$('organizer-status').hidden=true;$('organizer-app').hidden=false;
